import SwiftUI
import WebKit
import AppKit

/// Interactive Generative Artifacts & Canvas View (Frontier Super App).
/// Renders Mermaid.js architecture diagrams, SVG graphs, and HTML components
/// generated by agents directly inside conversation turns.
struct CanvasPreviewView: View {
    let language: String
    let code: String
    var isExpanded: Bool = false
    var onToggleExpand: (() -> Void)?

    @State private var isLoading: Bool = true

    init(language: String, code: String, isExpanded: Bool = false, onToggleExpand: (() -> Void)? = nil) {
        self.language = language.lowercased()
        self.code = code
        self.isExpanded = isExpanded
        self.onToggleExpand = onToggleExpand
    }

    public var body: some View {
        VStack(spacing: 0) {
            // Mini Canvas Header
            HStack(spacing: 6) {
                Image(systemName: iconForLanguage)
                    .font(.caption2)
                    .foregroundStyle(.purple)

                Text(titleForLanguage)
                    .font(.caption2.weight(.semibold))

                Spacer()

                if let onToggleExpand {
                    Button {
                        onToggleExpand()
                    } label: {
                        Image(systemName: isExpanded ? "arrow.down.right.and.arrow.up.left" : "arrow.up.left.and.arrow.down.right")
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                    .buttonStyle(.plain)
                    .help(isExpanded ? "ย่อขนาด" : "ขยายเต็มจอ")
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .background(Color.purple.opacity(0.08))
            .overlay(Divider().opacity(0.3), alignment: .bottom)

            // Webview Canvas
            CanvasWebViewRepresentable(htmlContent: generateHTML())
                .frame(minHeight: isExpanded ? 500 : 240)
        }
        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(Color.purple.opacity(0.2), lineWidth: 1))
    }

    private var iconForLanguage: String {
        switch language {
        case "mermaid": return "point.3.filled.connected.trianglepath.dotted"
        case "svg": return "paintpalette.fill"
        default: return "macwindow"
        }
    }

    private var titleForLanguage: String {
        switch language {
        case "mermaid": return "แผนภาพ Mermaid"
        case "svg": return "พรีวิว SVG"
        default: return "พรีวิว HTML (sandbox)"
        }
    }

    private func generateHTML() -> String {
        let isDarkMode = NSApp.effectiveAppearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
        let theme = isDarkMode ? "dark" : "default"
        let bgColor = isDarkMode ? "#1e1e1e" : "#fdfdfd"
        let textColor = isDarkMode ? "#e0e0e0" : "#222222"

        if language == "mermaid" {
            let escapedCode = code
                .replacingOccurrences(of: "&", with: "&amp;")
                .replacingOccurrences(of: "<", with: "&lt;")
                .replacingOccurrences(of: ">", with: "&gt;")

            return ArtifactPreviewSecurity.sandboxedHTML("""
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="utf-8">
                \(ArtifactPreviewSecurity.mermaidScriptTag)
                <style>
                    body {
                        margin: 0;
                        padding: 16px;
                        background: \(bgColor);
                        color: \(textColor);
                        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        min-height: 90vh;
                        overflow: auto;
                    }
                    .mermaid {
                        width: 100%;
                        display: flex;
                        justify-content: center;
                    }
                </style>
            </head>
            <body>
                <div class="mermaid">
                \(escapedCode)
                </div>
                <script>
                    mermaid.initialize({
                        startOnLoad: true,
                        theme: '\(theme)',
                        securityLevel: 'strict'
                    });
                </script>
            </body>
            </html>
            """, rendererScript: true)
        } else if language == "svg" {
            return ArtifactPreviewSecurity.sandboxedHTML("""
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="utf-8">
                <style>
                    body {
                        margin: 0;
                        padding: 16px;
                        background: \(bgColor);
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        min-height: 90vh;
                    }
                    svg {
                        max-width: 100%;
                        height: auto;
                    }
                </style>
            </head>
            <body>
                \(code)
            </body>
            </html>
            """)
        } else {
            return ArtifactPreviewSecurity.sandboxedHTML("""
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="utf-8">
                <style>
                    body {
                        margin: 0;
                        padding: 16px;
                        background: \(bgColor);
                        color: \(textColor);
                        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                    }
                </style>
            </head>
            <body>
                \(code)
            </body>
            </html>
            """)
        }
    }
}

private struct CanvasWebViewRepresentable: NSViewRepresentable {
    let htmlContent: String

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeNSView(context: Context) -> WKWebView {
        let view = ArtifactPreviewSecurity.makeWebView()
        view.navigationDelegate = context.coordinator
        view.setValue(false, forKey: "drawsBackground")
        return view
    }

    func updateNSView(_ nsView: WKWebView, context: Context) {
        guard context.coordinator.lastHTML != htmlContent else { return }
        context.coordinator.lastHTML = htmlContent
        nsView.loadHTMLString(htmlContent, baseURL: nil)
    }

    class Coordinator: NSObject, WKNavigationDelegate {
        var lastHTML: String?

        func webView(_ webView: WKWebView, decidePolicyFor action: WKNavigationAction,
                     decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
            decisionHandler(ArtifactPreviewSecurity.allowsNavigation(action.request.url, artifact: true) ? .allow : .cancel)
        }
    }
}
